"""Labelled synthetic scenes.

These are simplified tests. A single-pixel spike is not an empirically measured
Roman cosmic ray, and a Gaussian stamp is not a Roman PSF.
"""

from __future__ import annotations

import csv
import json
from pathlib import Path

import numpy as np

from romanartifactlens.io.wcsutil import tan_wcs_from_arrays

DEMO_SEED = 20261016
DEMO_NOTES = (
    "SYNTHETIC_TEST generated by romanartifactlens.fixtures. "
    "Not a Roman exposure. Not a calibrated detector artefact."
)


def build_demo_arrays(seed: int = DEMO_SEED) -> dict[str, object]:
    """128x128 scene with four labelled candidates and one multi-flag pixel."""

    rng = np.random.default_rng(seed)
    shape = (128, 128)
    background = 10.0
    noise_sigma = 0.8
    science = background + rng.normal(0.0, noise_sigma, size=shape)
    err = np.full(shape, noise_sigma, dtype=np.float64)
    dq = np.zeros(shape, dtype=np.uint32)
    _gaussian(science, 40.0, 64.0, 150.0, 1.5)
    _gaussian(science, 96.0, 40.0, 80.0, 1.5)
    _paint_disk(dq, 96.0, 40.0, 2.0, np.uint32(4))
    _gaussian(science, 1.0, 96.0, 90.0, 1.5)
    dq[90:103, 0:3] |= np.uint32(1)
    science[88:113, 68:93] = background
    science[100, 80] = background + 400.0
    dq[41, 62] = np.uint32(1 + 2 + 4 + 1024)
    candidates = [
        {
            "candidate_id": "clean-01",
            "x": 40.0,
            "y": 64.0,
            "fixture_label": "clean_point_source",
            "anomaly_score": 0.05,
        },
        {
            "candidate_id": "jump-01",
            "x": 96.0,
            "y": 40.0,
            "fixture_label": "jump_flag_overlap",
            "anomaly_score": 0.42,
        },
        {
            "candidate_id": "edge-01",
            "x": 1.0,
            "y": 96.0,
            "fixture_label": "edge_and_do_not_use",
            "anomaly_score": 0.20,
        },
        {
            "candidate_id": "spike-01",
            "x": 80.0,
            "y": 100.0,
            "fixture_label": "pixel_spike_no_jump_flag",
            "anomaly_score": 0.93,
        },
    ]
    wcs_arrays = _demo_wcs(shape)
    converter_wcs = tan_wcs_from_arrays(
        wcs_arrays["wcs_crpix"], wcs_arrays["wcs_crval"], wcs_arrays["wcs_cd"]
    )
    from romanartifactlens.io.wcsutil import SkyConverter

    converter = SkyConverter(converter_wcs)
    for row in candidates:
        ra, dec = converter.pixel_to_sky(row["x"], row["y"])
        row["ra"] = ra
        row["dec"] = dec
    return {
        "science": science,
        "err": err,
        "dq": dq,
        "candidates": candidates,
        "seed": seed,
        "background": background,
        "noise_sigma": noise_sigma,
        "units": "synthetic_counts",
        "uncertainty_model": "synthetic_gaussian_sigma",
        "notes": DEMO_NOTES,
        **wcs_arrays,
    }


def write_demo_files(directory: Path, seed: int = DEMO_SEED) -> dict[str, Path]:
    directory.mkdir(parents=True, exist_ok=True)
    scene = build_demo_arrays(seed)
    image_path = directory / "synthetic_image.npz"
    catalog_path = directory / "candidates.csv"
    ngrst_path = directory / "ngrst_candidates.csv"
    run_path = directory / "run.json"
    save_synthetic_npz(image_path, scene)
    _write_basic_catalog(catalog_path, scene["candidates"])
    _write_ngrst_catalog(ngrst_path, scene["candidates"])
    run_path.write_text(
        json.dumps(
            {
                "anomaly_model": "WITHIN_IMAGE_RANKING_ONLY",
                "note": "Not interpreted by RomanArtifactLens. Not a detection significance.",
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    return {
        "image": image_path,
        "catalog": catalog_path,
        "ngrst_catalog": ngrst_path,
        "run_json": run_path,
    }


def save_synthetic_npz(path: Path, scene: dict[str, object]) -> None:
    payload: dict[str, np.ndarray] = {
        "declaration": np.array("SYNTHETIC_TEST"),
        "science": np.asarray(scene["science"], dtype=np.float32),
        "units": np.array(str(scene.get("units", "synthetic_counts"))),
        "data_level": np.array(str(scene.get("data_level", "SYNTHETIC"))),
        "notes": np.array(str(scene.get("notes", DEMO_NOTES))),
        "uncertainty_model": np.array(str(scene.get("uncertainty_model", "synthetic_gaussian_sigma"))),
    }
    if scene.get("err") is not None:
        payload["err"] = np.asarray(scene["err"], dtype=np.float32)
    if scene.get("dq") is not None:
        payload["dq"] = np.asarray(scene["dq"], dtype=np.uint32)
    if scene.get("var_poisson") is not None:
        payload["var_poisson"] = np.asarray(scene["var_poisson"], dtype=np.float32)
    if scene.get("var_rnoise") is not None:
        payload["var_rnoise"] = np.asarray(scene["var_rnoise"], dtype=np.float32)
    if scene.get("var_flat") is not None:
        payload["var_flat"] = np.asarray(scene["var_flat"], dtype=np.float32)
    if "seed" in scene and scene["seed"] is not None:
        payload["seed"] = np.array(int(scene["seed"]))
    for key in ("wcs_crpix", "wcs_crval", "wcs_cd"):
        if key in scene:
            payload[key] = np.asarray(scene[key], dtype=np.float64)
    np.savez_compressed(path, **payload)


def build_controlled_case(
    *,
    shape: tuple[int, int] = (48, 48),
    x: float = 24.0,
    y: float = 24.0,
    science_value: float = 10.0,
    spike: float | None = None,
    err_value: float | None = 1.0,
    dq_value: int | None = 0,
    dq_at_center: int | None = None,
    data_level: str = "SYNTHETIC",
    units: str = "synthetic_counts",
    nan_box: tuple[int, int, int, int] | None = None,
    include_err: bool = True,
    var_poisson: float | None = None,
    var_rnoise: float | None = None,
    var_flat: float | None = None,
    uncertainty_model: str | None = "synthetic_constant_error",
) -> dict[str, object]:
    """A flat image with optional single-pixel edits for hand checks."""

    science = np.full(shape, science_value, dtype=np.float64)
    err = None if not include_err or err_value is None else np.full(shape, err_value, dtype=np.float64)
    dq = None if dq_value is None else np.full(shape, dq_value, dtype=np.uint32)
    row = int(np.round(y))
    col = int(np.round(x))
    if spike is not None:
        science[row, col] = science_value + spike
    if dq is not None and dq_at_center is not None:
        dq[row, col] = np.uint32(dq_at_center)
    if nan_box is not None:
        r0, r1, c0, c1 = nan_box
        science[r0:r1, c0:c1] = np.nan
        if err is not None:
            err[r0:r1, c0:c1] = np.nan
    scene: dict[str, object] = {
        "science": science,
        "err": err,
        "dq": dq,
        "data_level": data_level,
        "units": units,
        "uncertainty_model": uncertainty_model,
        "notes": DEMO_NOTES,
        "seed": 0,
    }
    if var_poisson is not None:
        scene["var_poisson"] = np.full(shape, var_poisson, dtype=np.float64)
    if var_rnoise is not None:
        scene["var_rnoise"] = np.full(shape, var_rnoise, dtype=np.float64)
    if var_flat is not None:
        scene["var_flat"] = np.full(shape, var_flat, dtype=np.float64)
    return scene


def noiseless_gaussian(
    *,
    shape: tuple[int, int] = (41, 41),
    x: float = 20.0,
    y: float = 20.0,
    amplitude: float = 50.0,
    sigma: float = 1.6,
    background: float = 3.0,
) -> dict[str, object]:
    science = np.full(shape, background, dtype=np.float64)
    _gaussian(science, x, y, amplitude, sigma)
    return {
        "science": science,
        "err": np.full(shape, 0.05, dtype=np.float64),
        "dq": np.zeros(shape, dtype=np.uint32),
        "units": "synthetic_counts",
        "uncertainty_model": "synthetic_constant_error",
        "data_level": "SYNTHETIC",
        "notes": "Noiseless synthetic Gaussian for the toy-PSF recovery test. Not a Roman PSF.",
        "seed": 1,
        "x": x,
        "y": y,
        "amplitude": amplitude,
        "sigma": sigma,
        "background": background,
    }


def ra_wrap_scene() -> dict[str, object]:
    """TAN WCS referenced at RA=0 so a pixel on one side lands near 359.9 deg."""

    shape = (32, 64)
    science = np.full(shape, 1.0, dtype=np.float64)
    scale = 0.01  # degrees per pixel, deliberately coarse
    crpix = np.array([32.0, 16.0])
    crval = np.array([0.0, 0.0])
    cd = np.array([[-scale, 0.0], [0.0, scale]])
    return {
        "science": science,
        "err": np.ones(shape, dtype=np.float64),
        "dq": np.zeros(shape, dtype=np.uint32),
        "units": "synthetic_counts",
        "uncertainty_model": "synthetic_constant_error",
        "data_level": "SYNTHETIC",
        "notes": DEMO_NOTES,
        "seed": 2,
        "wcs_crpix": crpix,
        "wcs_crval": crval,
        "wcs_cd": cd,
    }


def _demo_wcs(shape: tuple[int, int]) -> dict[str, np.ndarray]:
    scale = 0.11 / 3600.0
    return {
        "wcs_crpix": np.array([(shape[1] - 1) / 2.0, (shape[0] - 1) / 2.0]),
        "wcs_crval": np.array([10.0, -20.0]),
        "wcs_cd": np.array([[-scale, 0.0], [0.0, scale]], dtype=np.float64),
    }


def _gaussian(science: np.ndarray, x: float, y: float, amplitude: float, sigma: float) -> None:
    yy, xx = np.ogrid[0 : science.shape[0], 0 : science.shape[1]]
    science += amplitude * np.exp(-0.5 * ((xx - x) ** 2 + (yy - y) ** 2) / sigma**2)


def _paint_disk(dq: np.ndarray, x: float, y: float, radius: float, bit: np.uint32) -> None:
    yy, xx = np.ogrid[0 : dq.shape[0], 0 : dq.shape[1]]
    dq[np.hypot(xx - x, yy - y) <= radius] |= bit


def _write_basic_catalog(path: Path, candidates: list[dict[str, object]]) -> None:
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(
            handle,
            fieldnames=["candidate_id", "x", "y", "ra", "dec", "fixture_label"],
        )
        writer.writeheader()
        for row in candidates:
            writer.writerow(
                {
                    "candidate_id": row["candidate_id"],
                    "x": row["x"],
                    "y": row["y"],
                    "ra": f"{row['ra']:.10f}",
                    "dec": f"{row['dec']:.10f}",
                    "fixture_label": row["fixture_label"],
                }
            )


def _write_ngrst_catalog(path: Path, candidates: list[dict[str, object]]) -> None:
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(
            handle,
            fieldnames=[
                "label",
                "x_centroid",
                "y_centroid",
                "area",
                "snr",
                "anomaly_score",
                "anomaly_percentile",
                "ra",
                "dec",
                "known",
                "reference_id",
            ],
        )
        writer.writeheader()
        for index, row in enumerate(candidates):
            writer.writerow(
                {
                    "label": row["candidate_id"],
                    "x_centroid": row["x"],
                    "y_centroid": row["y"],
                    "area": 10 + index,
                    "snr": 8.0,
                    "anomaly_score": row["anomaly_score"],
                    "anomaly_percentile": 50 + index,
                    "ra": f"{row['ra']:.10f}",
                    "dec": f"{row['dec']:.10f}",
                    "known": "fixture",
                    "reference_id": f"synthetic-{index}",
                }
            )
